-- Owner-approved public discovery only. Commerce and media remain disabled.
CREATE VIEW marketplace_eligible_sources AS SELECT f.id AS offering_id,f.organization_id,f.location_id,f.version AS offering_version,COALESCE(c.version,0) AS canonical_version,json_object('name',f.name,'category',f.category,'brand',f.brand,'manufacturerReference',f.manufacturer_reference,'description',f.description,'unit',f.unit,'compatibility',json(f.compatibility_json),'priceMinor',f.price_minor,'currency','COP','priceIndicative',json('true'),'availability',f.availability,'lastUpdatedAt',f.updated_at,'partnerBusinessName',o.display_name,'country',o.country_code,'generalLocation',CASE WHEN f.location_id IS NOT NULL THEN l.city||', '||l.administrative_area ELSE '' END,'compatibilityNotice','Informational compatibility; workshop confirmation required','availabilityNotice','Informational availability; stock is not guaranteed') AS source_json FROM parts_offerings f JOIN org_organizations o ON o.id=f.organization_id LEFT JOIN org_locations l ON l.id=f.location_id AND l.organization_id=f.organization_id LEFT JOIN parts_canonical c ON c.id=f.canonical_part_id WHERE f.status='ACTIVE' AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND (f.location_id IS NULL OR l.status='ACTIVE') AND (f.canonical_part_id IS NULL OR (c.status='ACTIVE' AND c.brand_key=f.brand_key AND c.reference_key=f.reference_key)) AND (EXISTS(SELECT 1 FROM org_capabilities cap WHERE cap.organization_id=f.organization_id AND cap.code='PARTS') OR EXISTS(SELECT 1 FROM org_location_capabilities cap WHERE cap.organization_id=f.organization_id AND cap.location_id=f.location_id AND cap.code='PARTS'));
CREATE TABLE marketplace_listings(
 id TEXT PRIMARY KEY CHECK(length(id)=36 AND substr(id,15,1)='7'),
 organization_id TEXT NOT NULL REFERENCES org_organizations(id) ON DELETE RESTRICT,
 offering_id TEXT NOT NULL UNIQUE REFERENCES parts_offerings(id) ON DELETE RESTRICT,
 location_id TEXT,
 status TEXT NOT NULL CHECK(status IN ('DRAFT','PENDING_REVIEW','PUBLISHED','SUSPENDED')),
 version INTEGER NOT NULL CHECK(version BETWEEN 1 AND 9007199254740991),
 offering_version INTEGER NOT NULL,
 canonical_version INTEGER NOT NULL,
 snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json) AND json_type(snapshot_json)='object'),
 general_location TEXT NOT NULL CHECK(length(trim(general_location)) BETWEEN 1 AND 160),
 last_actor_account_id TEXT NOT NULL REFERENCES iam_accounts(id) ON DELETE RESTRICT,
 last_operation TEXT NOT NULL CHECK(last_operation IN ('marketplace.listing.create','marketplace.listing.submit','marketplace.listing.approve','marketplace.listing.reject','marketplace.listing.withdraw','marketplace.listing.suspend')),
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
 FOREIGN KEY(organization_id,location_id) REFERENCES org_locations(organization_id,id) ON DELETE RESTRICT
) STRICT;
CREATE INDEX marketplace_listing_status ON marketplace_listings(status,id);
CREATE TABLE marketplace_listing_history(
 id TEXT PRIMARY KEY,listing_id TEXT NOT NULL REFERENCES marketplace_listings(id) ON DELETE RESTRICT,
 organization_id TEXT NOT NULL REFERENCES org_organizations(id) ON DELETE RESTRICT,
 version INTEGER NOT NULL,status TEXT NOT NULL,operation TEXT NOT NULL,
 snapshot_json TEXT NOT NULL CHECK(json_valid(snapshot_json)),actor_account_id TEXT NOT NULL REFERENCES iam_accounts(id) ON DELETE RESTRICT,
 reason TEXT NOT NULL CHECK(length(trim(reason)) BETWEEN 1 AND 500),request_id TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),UNIQUE(listing_id,version)
) STRICT;
CREATE TRIGGER marketplace_listing_delete BEFORE DELETE ON marketplace_listings BEGIN SELECT RAISE(ABORT,'MARKETPLACE_IMMUTABLE'); END;
CREATE TRIGGER marketplace_history_update BEFORE UPDATE ON marketplace_listing_history BEGIN SELECT RAISE(ABORT,'MARKETPLACE_IMMUTABLE'); END;
CREATE TRIGGER marketplace_history_delete BEFORE DELETE ON marketplace_listing_history BEGIN SELECT RAISE(ABORT,'MARKETPLACE_IMMUTABLE'); END;
CREATE TRIGGER marketplace_listing_authority_insert BEFORE INSERT ON marketplace_listings WHEN NOT ((NEW.last_operation IN ('marketplace.listing.approve','marketplace.listing.reject','marketplace.listing.suspend') AND EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN platform_person_roles pr ON pr.person_id=p.id JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND r.scope='PLATFORM' AND r.code IN ('PLATFORM_SUPERADMIN','CATALOG_ADMIN') AND rp.permission_code='platform.catalog.manage')) OR (NEW.last_operation IN ('marketplace.listing.create','marketplace.listing.submit','marketplace.listing.withdraw') AND EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=NEW.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((NEW.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=NEW.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=NEW.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=NEW.location_id AND c.code='PARTS'))))) OR EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN development_automation_resources owned ON owned.account_id=d.account_id AND owned.resource_type='offering' AND owned.resource_id=NEW.offering_id JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation=NEW.last_operation AND a.status='ACTIVE' AND p.status='ACTIVE' AND d.organization_id=NEW.organization_id AND d.location_id=NEW.location_id AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND EXISTS(SELECT 1 FROM org_organizations o JOIN org_locations l ON l.organization_id=o.id WHERE o.id=d.organization_id AND l.id=d.location_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND o.display_name='MotorBaldi Development Validation Workshop' AND l.status='ACTIVE' AND l.name='MotorBaldi Development Workshop Site') AND EXISTS(SELECT 1 FROM org_memberships m JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id JOIN org_membership_locations ml ON ml.membership_id=m.id AND ml.organization_id=m.organization_id WHERE m.person_id=a.person_id AND m.organization_id=d.organization_id AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND m.location_scope_type='SELECTED_LOCATIONS' AND ml.location_id=d.location_id AND r.code='DEVELOPMENT_AUTOMATION' AND r.scope='ORGANIZATION' AND rp.permission_code='org.parts.manage') AND (NEW.last_operation NOT IN ('marketplace.listing.approve','marketplace.listing.reject','marketplace.listing.suspend') OR EXISTS(SELECT 1 FROM platform_person_roles pr JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE pr.person_id=a.person_id AND r.scope='PLATFORM' AND r.code='DEVELOPMENT_AUTOMATION' AND rp.permission_code='platform.catalog.manage')))) BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
CREATE TRIGGER marketplace_listing_authority_update BEFORE UPDATE ON marketplace_listings WHEN NOT ((NEW.last_operation IN ('marketplace.listing.approve','marketplace.listing.reject','marketplace.listing.suspend') AND EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN platform_person_roles pr ON pr.person_id=p.id JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND r.scope='PLATFORM' AND r.code IN ('PLATFORM_SUPERADMIN','CATALOG_ADMIN') AND rp.permission_code='platform.catalog.manage')) OR (NEW.last_operation IN ('marketplace.listing.create','marketplace.listing.submit','marketplace.listing.withdraw') AND EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=NEW.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((NEW.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=NEW.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=NEW.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (NEW.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=NEW.location_id AND c.code='PARTS'))))) OR EXISTS(SELECT 1 FROM development_automation_identities d JOIN development_automation_authorizations ctx ON ctx.account_id=d.account_id AND ctx.credential_version=d.credential_version JOIN development_automation_resources owned ON owned.account_id=d.account_id AND owned.resource_type='offering' AND owned.resource_id=NEW.offering_id JOIN iam_accounts a ON a.id=d.account_id JOIN iam_people p ON p.id=a.person_id WHERE d.account_id=NEW.last_actor_account_id AND d.status='ACTIVE' AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now') AND ctx.operation=NEW.last_operation AND a.status='ACTIVE' AND p.status='ACTIVE' AND d.organization_id=NEW.organization_id AND d.location_id=NEW.location_id AND EXISTS(SELECT 1 FROM governance_environment_metadata WHERE singleton=1 AND environment='development') AND EXISTS(SELECT 1 FROM org_organizations o JOIN org_locations l ON l.organization_id=o.id WHERE o.id=d.organization_id AND l.id=d.location_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND o.display_name='MotorBaldi Development Validation Workshop' AND l.status='ACTIVE' AND l.name='MotorBaldi Development Workshop Site') AND EXISTS(SELECT 1 FROM org_memberships m JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id JOIN org_membership_locations ml ON ml.membership_id=m.id AND ml.organization_id=m.organization_id WHERE m.person_id=a.person_id AND m.organization_id=d.organization_id AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND m.location_scope_type='SELECTED_LOCATIONS' AND ml.location_id=d.location_id AND r.code='DEVELOPMENT_AUTOMATION' AND r.scope='ORGANIZATION' AND rp.permission_code='org.parts.manage') AND (NEW.last_operation NOT IN ('marketplace.listing.approve','marketplace.listing.reject','marketplace.listing.suspend') OR EXISTS(SELECT 1 FROM platform_person_roles pr JOIN authz_roles r ON r.id=pr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE pr.person_id=a.person_id AND r.scope='PLATFORM' AND r.code='DEVELOPMENT_AUTOMATION' AND rp.permission_code='platform.catalog.manage')))) BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
CREATE TRIGGER marketplace_listing_insert BEFORE INSERT ON marketplace_listings WHEN NEW.status<>'DRAFT' OR NEW.version<>1 OR NEW.last_operation<>'marketplace.listing.create' OR NOT EXISTS(SELECT 1 FROM marketplace_eligible_sources s WHERE s.offering_id=NEW.offering_id AND s.organization_id=NEW.organization_id AND s.location_id IS NEW.location_id AND s.offering_version=NEW.offering_version AND s.canonical_version=NEW.canonical_version AND json_set(s.source_json,'$.generalLocation',NEW.general_location)=NEW.snapshot_json AND (s.location_id IS NULL OR json_extract(s.source_json,'$.generalLocation')=NEW.general_location)) BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
CREATE TRIGGER marketplace_listing_update BEFORE UPDATE ON marketplace_listings WHEN NEW.id IS NOT OLD.id OR NEW.organization_id IS NOT OLD.organization_id OR NEW.offering_id IS NOT OLD.offering_id OR NEW.created_at IS NOT OLD.created_at OR NEW.version<>OLD.version+1 OR NOT ((NEW.last_operation='marketplace.listing.submit' AND OLD.status IN ('DRAFT','SUSPENDED','PUBLISHED','PENDING_REVIEW') AND NEW.status='PENDING_REVIEW') OR (NEW.last_operation='marketplace.listing.approve' AND OLD.status='PENDING_REVIEW' AND NEW.status='PUBLISHED') OR (NEW.last_operation='marketplace.listing.reject' AND OLD.status='PENDING_REVIEW' AND NEW.status='DRAFT') OR (NEW.last_operation IN ('marketplace.listing.withdraw','marketplace.listing.suspend') AND NEW.status='SUSPENDED')) OR (NEW.last_operation IN ('marketplace.listing.submit','marketplace.listing.approve') AND NOT EXISTS(SELECT 1 FROM marketplace_eligible_sources s WHERE s.offering_id=NEW.offering_id AND s.organization_id=NEW.organization_id AND s.location_id IS NEW.location_id AND s.offering_version=NEW.offering_version AND s.canonical_version=NEW.canonical_version AND json_set(s.source_json,'$.generalLocation',NEW.general_location)=NEW.snapshot_json AND (s.location_id IS NULL OR json_extract(s.source_json,'$.generalLocation')=NEW.general_location))) OR (NEW.last_operation<>'marketplace.listing.submit' AND (NEW.snapshot_json IS NOT OLD.snapshot_json OR NEW.offering_version<>OLD.offering_version OR NEW.canonical_version<>OLD.canonical_version OR NEW.location_id IS NOT OLD.location_id OR NEW.general_location IS NOT OLD.general_location)) BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
CREATE TRIGGER marketplace_history_insert BEFORE INSERT ON marketplace_listing_history WHEN NOT EXISTS(SELECT 1 FROM marketplace_listings l JOIN governance_audit_events a ON a.resource_id=l.id AND a.actor_id=l.last_actor_account_id AND a.action=l.last_operation WHERE l.id=NEW.listing_id AND l.organization_id=NEW.organization_id AND l.version=NEW.version AND l.status=NEW.status AND l.snapshot_json=NEW.snapshot_json AND l.last_operation=NEW.operation AND l.last_actor_account_id=NEW.actor_account_id AND a.request_id=NEW.request_id AND a.resource_type='marketplace') BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
CREATE TRIGGER marketplace_listing_submit_prior_scope BEFORE UPDATE ON marketplace_listings WHEN NEW.last_operation='marketplace.listing.submit' AND NOT EXISTS(SELECT 1 FROM iam_accounts a JOIN iam_people p ON p.id=a.person_id JOIN auth_users u ON u.id=a.id JOIN org_memberships m ON m.person_id=p.id JOIN org_organizations o ON o.id=m.organization_id JOIN org_membership_roles mr ON mr.membership_id=m.id JOIN authz_roles r ON r.id=mr.role_id JOIN authz_role_permissions rp ON rp.role_id=r.id WHERE a.id=NEW.last_actor_account_id AND a.status='ACTIVE' AND p.status='ACTIVE' AND u.email_verified=1 AND u.two_factor_enabled=1 AND EXISTS(SELECT 1 FROM auth_two_factors tf WHERE tf.user_id=u.id AND tf.verified=1) AND o.id=OLD.organization_id AND o.status='ACTIVE' AND o.verification_status='VERIFIED' AND m.status='ACTIVE' AND m.valid_from<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND (m.valid_to IS NULL OR m.valid_to>strftime('%Y-%m-%dT%H:%M:%fZ','now')) AND r.scope='ORGANIZATION' AND r.code IN ('OWNER','ADMIN') AND rp.permission_code='org.parts.manage' AND ((OLD.location_id IS NULL AND m.location_scope_type='ALL_LOCATIONS') OR (OLD.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_locations l WHERE l.id=OLD.location_id AND l.organization_id=o.id AND l.status='ACTIVE') AND (m.location_scope_type='ALL_LOCATIONS' OR EXISTS(SELECT 1 FROM org_membership_locations ml WHERE ml.membership_id=m.id AND ml.organization_id=o.id AND ml.location_id=OLD.location_id)))) AND (EXISTS(SELECT 1 FROM org_capabilities c WHERE c.organization_id=o.id AND c.code='PARTS') OR (OLD.location_id IS NOT NULL AND EXISTS(SELECT 1 FROM org_location_capabilities c WHERE c.organization_id=o.id AND c.location_id=OLD.location_id AND c.code='PARTS')))) AND NOT EXISTS(SELECT 1 FROM development_automation_identities d WHERE d.account_id=NEW.last_actor_account_id) BEGIN SELECT RAISE(ABORT,'MARKETPLACE_BOUNDARY'); END;
